import { test, expect } from '@playwright/test';

test.describe('Sticky Header Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should keep header visible while scrolling', async ({ page }) => {
    // Verify header is visible initially
    const header = page.getByRole('banner');
    await expect(header).toBeVisible();

    // Verify header has correct sticky class
    const stickyClass = page.getByRole('heading').first().getAttribute('class');
    expect(stickyClass).toContain('sticky-header');

    // Scroll down to test stickiness
    await page.evaluate(() => {
      window.scrollTo(0, window.innerHeight);
    });

    // Verify header is still visible after scrolling
    await expect(header).toBeVisible();

    // Verify header is positioned at the top of the viewport
    const headerPosition = page.getByRole('heading').first().getBoundingClientRect();
    expect(headerPosition.top).toBeLessThanOrEqual(0);

    // Scroll back up to test header visibility
    await page.evaluate(() => {
      window.scrollTo(0, 0);
    });

    // Verify header is still visible after scrolling back up
    await expect(header).toBeVisible();
  });

  test('should update header content on route change', async ({ page }) => {
    // Verify initial header content
    const header = page.getByRole('banner');
    await expect(header).toContainText('Dashboard');

    // Navigate to a different route
    await page.route('**/settings', route => {
      route.continue();
    });

    // Verify header content updates to reflect new route
    const headerContent = page.getByRole('heading').first().textContent();
    expect(headerContent).toContainText('Settings');

    // Verify sticky class is still present
    const stickyClass = page.getByRole('heading').first().getAttribute('class');
    expect(stickyClass).toContain('sticky-header');

    // Verify header is still visible after route change
    await expect(header).toBeVisible();
  });
});
